protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) throw new NullPointerException("tour is null");
    if (graph == null) throw new NullPointerException("graph is null");
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), new ArrayList<>(), 0.0);
    }
    Set<E> remaining = new HashSet<>(tour);
    E first = remaining.iterator().next();
    V start = graph.getEdgeSource(first);
    V current = start;
    List<V> vertexList = new ArrayList<>();
    vertexList.add(start);
    List<E> edgeList = new ArrayList<>();
    double weight = 0.0;
    boolean undirected = graph.getType().isUndirected();
    while (!remaining.isEmpty()) {
        E found = null;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (undirected) {
                if (src.equals(current) || tgt.equals(current)) {
                    found = e;
                    break;
                }
            } else {
                if (src.equals(current)) {
                    found = e;
                    break;
                }
            }
        }
        if (found == null) {
            throw new IllegalArgumentException("Edges do not form a connected tour");
        }
        edgeList.add(found);
        weight += graph.getEdgeWeight(found);
        V src = graph.getEdgeSource(found);
        V tgt = graph.getEdgeTarget(found);
        V next;
        if (undirected) {
            next = src.equals(current) ? tgt : src;
        } else {
            next = tgt;
        }
        vertexList.add(next);
        current = next;
        remaining.remove(found);
    }
    return new GraphWalk<>(graph, start, current, vertexList, edgeList, weight);
}

