private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) return result;
    // Build a sorted list of integer keys for efficient lookup
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys) {
        if (k != null) {
            try {
                sorted.add((Integer) k);
            } catch (ClassCastException e) {
                // Skip non‑Integer keys
            }
        }
    }
    Collections.sort(sorted);
    // Compute lower bound for each key in the original order
    for (K k : keys) {
        if (k == null) {
            result.add(Integer.MIN_VALUE);
            continue;
        }
        Integer key;
        try {
            key = (Integer) k;
        } catch (ClassCastException e) {
            result.add(Integer.MIN_VALUE);
            continue;
        }
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        }
        int lowerIdx = idx - 1;
        if (lowerIdx >= 0) {
            result.add(sorted.get(lowerIdx));
        } else {
            result.add(Integer.MIN_VALUE);
        }
    }
    return result;
}

