private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                try {
                    if (graph.getEdge(v1, v2) == null) {
                        return false;
                    }
                } catch (IllegalArgumentException e) {
                    return false;
                }
            }
        }
    }
    return true;
}

