                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                    i += 5; // skip the entire \uXXXX sequence
                } catch (NumberFormatException e) {
                    // Not a valid hex sequence; treat as literal
                    sb.append('\\').append(next);
                    i++; // skip the 'u'
                }
            } else {
                // Escape any other character (including another backslash)
                sb.append(next);
                i++; // skip the escaped character
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

