public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue; // skip empty segments caused by consecutive slashes
        }
        String value = part;
        if (decode) {
            try {
                value = URLDecoder.decode(part, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; fallback to original
                value = part;
            }
        }
        // In PathSegmentImpl, the second argument indicates whether the segment is encoded.
        // If we decoded, the segment is not encoded.
        segments.add(new PathSegmentImpl(value, !decode));
    }
    return segments;
}

