public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    int start = Math.max(2, desiredCapacity);
    int upperBound = start;
    if (desiredCapacity >= 1000) {
        long ub = (long) start * 111 / 100; // 1.11 * start
        upperBound = (ub > Integer.MAX_VALUE) ? Integer.MAX_VALUE : (int) ub;
    }
    for (int n = start; n <= upperBound; n++) {
        if (isPrime(n)) {
            return n;
        }
    }
    // If no prime found within the 11% range, continue searching beyond the bound
    for (int n = upperBound + 1; ; n++) {
        if (isPrime(n)) {
            return n;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

