public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    try {
        buffer.clear();
        // Encode the message into the buffer
        schema.writeTo(buffer, message);
        byte[] data = buffer.toByteArray();
        int len = data.length;
        // Write the length as a 4‑byte big‑endian prefix
        out.write((len >>> 24) & 0xFF);
        out.write((len >>> 16) & 0xFF);
        out.write((len >>> 8) & 0xFF);
        out.write(len & 0xFF);
        // Write the actual message bytes
        out.write(data);
        return len;
    } catch (IOException e) {
        throw e; // propagate I/O errors
    } catch (Exception e) {
        throw new IOException("Failed to write delimited message", e);
    }
}

